record.field:
for employee in records:
    partner = employee.work_contact_id
    if not partner:
        partner = env['res.partner'].sudo().create({
            'name': employee.name,
            'company_type': 'person',
        })
        employee.sudo().work_contact_id = partner.id
    employee_type = env.ref(
        'partner_type_kmitl.partner_type_employee', raise_if_not_found=False
    )
    if employee_type:
        partner.sudo().partner_type_id = employee_type.id
    else:
        log(
            "hr_partner_type_kmitl: partner_type_kmitl.partner_type_employee "
            "not found; left %s's work contact without a partner type."
            % employee.name,
            level='warning',
        )
